import React from 'react';
import Personal from '../komponen/Personal';
import Programming from '../komponen/Programming';
import Volunteer from '../komponen/Volunteer';

import { useSpring, animated } from 'react-spring';

function Details(props) {

    const style = useSpring({opacity: 1, from: {opacity: 0}});

    return(
        <animated.div className="g-card-info" style={style} fluid={true}>
            <p className="g-card-title">{props.name}</p>
            <p className="g-card-sub-title title-sub">{props.sub}</p>
            {Content(props.id)}
        </animated.div>
    );

}



function Content(id) {
  if(id==0) {
    return <Personal />
  } else if(id==1) {
    return <Programming />
  } else if(id==2){
    return <Volunteer />
  }
}
/*
<a href={props.link} target="_blank" rel="noopener noreferrer">View</a>
*/
export default Details;
