import React from 'react';
import Row from 'react-bootstrap/Row';
import {BrowserRouter as Router, Route, Link } from 'react-router-dom';

import Personal from '../komponen/Personal';
import Programming from '../komponen/Programming';
import Volunteer from '../komponen/Volunteer';
import Abouts from '../komponen/Abouts';
import Container from 'react-bootstrap/Container';

import Sample from '../bahan/Sample.jpg';
import Green from '../bahan/green.png';
import Yellow from '../bahan/yellow.jpg';
import Blue from '../bahan/blue.jpg';

class Bio extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      arr: [
        {
          id: 0,
          name: 'I am Muhammad Mirza Fathan Al Arsyad',
          sub: 'People call me Mirza, and some (Madrasah Aliyah friends) call me \'Miju\' (for a reason I don\'t know).',
          img: Green,
          link: "/personal",
          pilih: false,
          go: false
        },
        {
          id: 1,
          name: 'Programming Experience',
          sub: 'List of my programming experiences',
          img: Blue,
          pilih: false,
          go: false
        },
        {
          id: 2,
          name: 'Volunteer Experience',
          sub: 'Most of them are organization-related activities.',
          img: Yellow,
          pilih: false,
          go: false
        }
      ]
    }
  }

  BioClick = (id, bio) => {

    let arr = [...this.state.arr];

    if(arr[id].pilih) {
      arr[id].pilih = false;
    } else {
      arr[id].pilih = true;
    }

    arr.forEach(it => {
      if(it.id !== id) {
        it.pilih = false;
      }
    });

    this.setState({
      arr
    });

  }

  makeArr = (arr) => {
      return arr.map(
        it => {
          return <Abouts
            item={it}
            click={(e => this.BioClick(it.id, e))}
            key={it.id} />
        }
      )
  }

  render() {
    return(
      <Container fluid={true}>
        <Row className="justify-content-around">
         {this.makeArr(this.state.arr)}
        </Row>
      </Container>

    );
  }
}

export default Bio;

