import React from 'react';

import {BrowserRouter as Router, Route, Link } from 'react-router-dom';
import Container from 'react-bootstrap/Container';
import Navbar from 'react-bootstrap/Navbar';
import Nav from 'react-bootstrap/Nav';

import logo from './logo.svg';
import './App.css';
import Footer from './komponen/Footer';
import Beranda from './page/Beranda';
import Projects from './page/Projects';
import Blog from './page/Blog';
import Manhaj from './page/Manhaj';

class App extends React.Component {

  constructor(props) {
    super(props);
    this.state = {
      title: 'Muhammad Mirza Fathan',
      headerLinks: [
        { title: 'Home', path: '/' },
        { title: 'Projects', path: '/projects' },
        { title: 'Blog', path: '/blog'},
        { title: 'Manhaj', path: '/manhaj' }
      ],
      home: {
        title: 'Assalamu \'alaykum.',
        subTitle: 'Welcome friends رحمكم الله',
        text: 'This is Mirza\'s personal website. Have a nice day!'
      },
      projects: {
        title: 'Projects',
        subTitle: 'My self projects are coming soon'
      },
      blog: {
        title: 'Blog',
        subTitle: 'Some of my writings in the Medium'
      },
      manhaj: {
        title: 'Some Recommended Islamic Articles',
        subTitle: 'Please have a read. May Allah bless you.'
      }

    }
  }


  render() {
    return(
      <Router>
        <Container className="p-0" fluid={true}>
          <Navbar className="rounded border m-2" bg="transparent" expand="lg">
            <Navbar.Brand className="font-weight-bolder">Muhammad Mirza Fathan</Navbar.Brand>
            <Navbar.Toggle className="border-0" aria-controls="navbar-toggle" />
            <Navbar.Collapse id="navbar-toggle">
              <Nav className="ml-auto">
                <Link className="nav-link" to="/">Home</Link>
                <Link className="nav-link" to="/projects">Projects</Link>
                <Link className="nav-link" to="/blog">Blog</Link>
                <Link className="nav-link" to="/manhaj">Manhaj</Link>
              </Nav>
            </Navbar.Collapse>
          </Navbar>

          <Route path="/" exact render={() =>
            <Beranda
            title={this.state.home.title}
            subTitle={this.state.home.subTitle}
            text={this.state.home.text} /> }
          />
          <Route path="/projects" render={() =>
            <Projects
            title={this.state.projects.title}
            subTitle={this.state.projects.subTitle} /> }
          />
          <Route path="/blog" render={() =>
            <Blog
            title={this.state.blog.title}
            subTitle={this.state.blog.subTitle} /> }
          />
          <Route path="/manhaj" render={() =>
            <Blog
            title={this.state.manhaj.title}
            subTitle={this.state.manhaj.subTitle} /> }
          />


          <Footer />
        </Container>
      </Router>


    );
  }
}

export default App;
